<script setup lang="ts">
import { ref,computed } from 'vue'
import { useRoute } from 'vue-router'
import { useProtocol } from '../stores/protocol'
import { exchangeSamples,type ExchangeSystem } from '../domain/protocol'
import { usePlatform,roleNames } from '../stores/platform'
import { duties, type Duty } from '../domain/identity'
import { navigation } from '../navigation'
import type { Resource,Role } from '../domain/types'
import { download,csv } from '../utils/files'
import PageHead from '../components/PageHead.vue'
import Icon from '../components/Icon.vue'
import Badge from '../components/Badge.vue'
import Modal from '../components/Modal.vue'
import Empty from '../components/Empty.vue'
const protocol=useProtocol(),s=usePlatform(),route=useRoute(),page=computed(()=>String(route.params.page));const search=ref(''),tab=ref(String(route.query.tab||'角色权限')),resource=ref<Resource|null>(null),addOpen=ref(false),mapping=ref(false),chosenSystem=ref('集团HR'),settings=ref({...s.data.settings,weights:[...s.data.settings.weights]}),resourceForm=ref({title:'',category:'工业技术',content:'',author:'自制演示资料',pages:1})
const category=ref('全部分类'),editingId=ref(''),deleteResource=ref<Resource|null>(null),exchangePreview=ref(false),receipt=ref('')
function editResource(r:Resource){editingId.value=r.id;resourceForm.value={title:r.title,category:r.category,content:r.content,author:r.author,pages:r.pages};addOpen.value=true}
function removeResource(){s.run(()=>{s.requireDuty('resources');if(deleteResource.value!.status==='已发布')throw new Error('请先下架资料再删除');s.data.resources=s.data.resources.filter(r=>r.id!==deleteResource.value!.id);s.audit('学习资源','删除资料',deleteResource.value!.id);deleteResource.value=null;s.notify('资料已删除，操作日志保留')})}
const titles:Record<string,[string,string]>={resources:['学习资源','汇集职业知识与参考资料，为命题、学习和考评提供支持。'],integrations:['接口中心','查看模拟数据交换、字段映射与失败重试，实现业务协同。'],permissions:['权限与审计','按角色组织业务入口，关键操作保留记录，支撑过程追溯。'],settings:['系统设置','配置评分规则，管理数据备份。']}
const title=computed(()=>titles[page.value]||titles.resources!)
const books=computed(()=>s.data.resources.filter(r=>(s.can('resources')||r.status==='已发布')&&(category.value==='全部分类'||r.category===category.value)&&(!search.value||r.title.includes(search.value))))
const logs=computed(()=>s.data.logs.filter(l=>!search.value||[l.actor,l.module,l.action,l.object].some(v=>v.includes(search.value))))
function addResource(){s.run(()=>{s.requireDuty('resources');if(!resourceForm.value.title.trim()||!resourceForm.value.content.trim())throw new Error('请填写资料名称和正文，或上传文本资料');if(editingId.value){const old=s.data.resources.find(r=>r.id===editingId.value)!;Object.assign(old,resourceForm.value);old.status='草稿';s.audit('学习资源','修改资料并转草稿',old.id)}else{s.data.resources.unshift({...resourceForm.value,id:'BOOK-'+Date.now(),status:'草稿'});s.audit('学习资源','新增资料',resourceForm.value.title)}addOpen.value=false;s.notify('资料已保存为草稿，发布后供用户阅读')})}
async function loadText(e:Event){const f=(e.target as HTMLInputElement).files?.[0];if(f){if(f.size>1024*1024){s.notify('请使用1MB以内的自制文本样例',true);return}resourceForm.value.content=await f.text();if(!resourceForm.value.title)resourceForm.value.title=f.name.replace(/\.txt$/,'')}}
function changeResource(r:Resource){s.requireDuty('resources');r.status=r.status==='已发布'?'已下架':'已发布';s.audit('学习资源',r.status,r.id);s.notify(`资料${r.status}`)}
function syncSystem(){s.run(()=>{protocol.applyExchange(chosenSystem.value as ExchangeSystem);exchangePreview.value=false})}
function saveSettings(){s.run(()=>{s.requireDuty('reviewAdmin');if(!Number.isFinite(settings.value.threshold)||settings.value.threshold<0||settings.value.threshold>30)throw new Error('差值阈值须在0～30之间');if(settings.value.scoreRule==='权重评分'&&(settings.value.weights.some(w=>w<0)||Math.abs(settings.value.weights.reduce((a,b)=>a+b,0)-1)>.00001))throw new Error('两位评委权重须非负且总和为1');s.data.settings={...settings.value,weights:[...settings.value.weights],early:15,late:30};s.audit('系统设置','更新评分规则','Demo评分参数');s.notify('设置已保存，后续提交使用新规则，已核定成绩不重算')})}
function exportLogs(){csv('业务审计.csv',[['时间','操作人','模块','动作','对象','结果'],...logs.value.map(l=>[l.time,l.actor,l.module,l.action,l.object,l.result])]);s.audit('审计日志','导出日志',`${logs.value.length}条`)}
function backup(){download('hfplatform-demo-backup.json',JSON.stringify(s.data,null,2),'application/json');s.audit('系统设置','导出合成备份','当前浏览器数据')}
</script>
<template><PageHead :title="title[0]" :subtitle="title[1]" eyebrow="平台服务 / 协同支撑"><button v-if="page==='resources'&&s.can('resources')" class="button primary" @click="editingId='';resourceForm={title:'',category:'工业技术',content:'',author:'自制演示资料',pages:1};addOpen=true"><Icon name="Plus" :size="16"/>新增学习资料</button><RouterLink v-if="page==='integrations'" class="button primary" to="/protocol/integration">业务数据交换</RouterLink><button v-if="page==='integrations'" class="button" @click="mapping=true"><Icon name="ArrowLeftRight" :size="16"/>字段映射</button><button v-if="page==='permissions'" class="button" @click="exportLogs"><Icon name="Download" :size="16"/>导出日志</button></PageHead>
<template v-if="page==='resources'"><div class="resource-hero"><div><span class="eyebrow">LEARNING & RESOURCES</span><h2>让知识积累，成为技能进阶的力量</h2><p>职业标准参考 · 专业理论 · 技能实践</p></div><Icon name="BookOpenText" :size="100"/></div><div class="filter-bar panel"><div class="input-icon"><Icon name="Search" :size="17"/><input v-model="search" placeholder="搜索资料名称…"/></div><select v-model="category" aria-label="资源分类"><option>全部分类</option><option v-for="c in [...new Set(s.data.resources.map(r=>r.category))]">{{c}}</option></select><span class="filter-meta">{{books.length}} 份自制合成资料</span></div><div class="book-grid"><article v-for="(b,i) in books" class="panel book-card"><div class="book-cover" :class="'cover-'+i%3"><span>职业技能 · 学习资料</span><h3>{{b.title}}</h3><Icon name="BookOpen" :size="40"/><small>演示专用 / DEMO RESOURCE</small></div><div class="book-info"><div><span class="pill">{{b.category}}</span><Badge :text="b.status"/></div><h3>{{b.title}}</h3><p>{{b.author}} · {{b.pages}}页标注</p><div class="action-group"><button class="button primary" @click="resource=b"><Icon name="BookOpen" :size="16"/>阅读资料</button><button v-if="s.can('resources')" class="text-button" @click="s.run(()=>changeResource(b))">{{b.status==='已发布'?'下架':'发布'}}</button><button v-if="s.can('resources')" class="text-button" @click="editResource(b)">编辑</button><button v-if="s.can('resources')&&b.status!=='已发布'" class="text-button" @click="deleteResource=b">删除</button></div></div></article></div><Empty v-if="!books.length"/></template>
<template v-if="page==='integrations'"><div class="integration-grid"><article v-for="sys in ['集团HR','原考务系统','集团认定系统','人社题库']" class="panel integration-card"><span class="icon-circle" :class="sys==='人社题库'?'violet':'blue'"><Icon :name="sys==='集团HR'?'Users':sys==='人社题库'?'LibraryBig':'Cable'" :size="23"/></span><h3>{{sys}}</h3><p>{{sys==='集团HR'?'组织与人员主数据':sys==='原考务系统'?'计划、场次与考生名单':sys==='集团认定系统'?'成绩与核定结果回传':'公开资源双向交换'}}</p><Badge text="模拟适配器"/></article></div><section class="panel spaced"><div class="panel-head"><h3>数据交换记录</h3><div class="inline-actions"><select v-model="chosenSystem"><option>集团HR</option><option>原考务系统</option><option>人社题库</option></select><button class="button primary small" @click="exchangePreview=true"><Icon name="RefreshCw" :size="15"/>模拟同步</button></div></div><div class="table-scroll"><table><thead><tr><th>对接系统 / 方向</th><th>交换对象</th><th>幂等键</th><th>时间</th><th>次数</th><th>状态</th><th>操作</th></tr></thead><tbody><tr v-for="i in s.data.integrations"><td>{{i.system}}<small>{{i.direction}}</small></td><td>{{i.object}}<small v-if="i.error" class="text-red">{{i.error}}</small></td><td><code>{{i.key}}</code></td><td>{{i.time}}</td><td>{{i.count}}</td><td><Badge :text="i.status"/></td><td><button v-if="i.status==='失败'" class="text-button" @click="s.run(()=>s.retryIntegration(i.id))">原键重试</button><button v-else class="text-button" @click="receipt=JSON.stringify({receipt:'ACK-'+i.key,system:i.system,object:i.object,status:i.status,key:i.key,attempts:i.count},null,2)">回执</button></td></tr></tbody></table></div></section><div class="notice spaced">所有同步动作在本地模拟执行。真实SSO、HR、人社题库、公安/人脸接口须提供正式授权、网络条件与接口契约后联调。</div></template>
<template v-if="page==='permissions'"><section class="panel"><div class="tabs"><button v-for="t in ['角色权限','业务审计']" :class="{active:tab===t}" @click="tab=t">{{t}}</button></div><template v-if="tab==='角色权限'"><div class="notice">人员、职责与任务分开管理；此表读取当前生效授权。具体兼任、特批及入库职责为演示配置，不代表已确认的制度。</div><div class="table-scroll"><table><thead><tr><th>演示人员</th><th>所属机构</th><th>职责</th><th>范围</th><th>状态</th></tr></thead><tbody><tr v-for="p in s.people"><td>{{p.name}}</td><td>{{p.org}}</td><td>{{p.duties.map(d=>duties[d]).join('、')}}</td><td>{{p.kinds.join(' / ')}}</td><td>{{p.enabled?'已授权':'已停用'}}</td></tr></tbody></table></div></template><template v-else><div class="filter-bar"><div class="input-icon"><Icon name="Search" :size="16"/><input v-model="search" placeholder="搜索人员、动作、业务对象…"/></div><span class="filter-meta">最近{{logs.length}}条 · 保留上限500条</span></div><div class="table-scroll"><table><thead><tr><th>时间</th><th>操作人</th><th>模块</th><th>动作</th><th>对象</th><th>结果</th></tr></thead><tbody><tr v-for="l in logs.slice(0,100)"><td>{{l.time}}</td><td>{{l.actor}}</td><td>{{l.module}}</td><td>{{l.action}}</td><td><code>{{l.object}}</code></td><td><Badge :text="l.result"/></td></tr></tbody></table></div></template></section></template>
<template v-if="page==='settings'"><div class="settings-layout"><section class="panel settings-panel"><div class="panel-head"><h3>评分规则配置</h3><span class="subtle-label">当前规则参数</span></div><div class="form-grid"><label>差值仲裁阈值（分）<input v-model.number="settings.threshold" type="number" min="0" max="30"/></label><label>核分方式<select v-model="settings.scoreRule"><option>平均分</option><option>权重评分</option><option>去极值平均</option></select></label><template v-if="settings.scoreRule==='权重评分'"><label>评委一权重<input v-model.number="settings.weights[0]" type="number" min="0" max="1" step=".1"/></label><label>评委二权重<input v-model.number="settings.weights[1]" type="number" min="0" max="1" step=".1"/></label></template><div v-if="settings.scoreRule==='去极值平均'" class="notice span-two">去极值规则使用3位模拟评委，去掉一个最高分与一个最低分。人数不足时保持待评。</div><label>迟到限制<input :value="'超过30分钟禁止入场'" disabled/></label><label>提前交卷限制<input :value="'开考15分钟内禁止交卷'" disabled/></label></div><div class="notice">配置应用于后续评分提交，已核定成绩不自动重算。每次修改保留审计日志。</div><button class="button primary" @click="saveSettings"><Icon name="Save" :size="16"/>保存规则</button></section><section v-if="s.can('access')" class="panel"><div class="panel-head"><h3>数据备份</h3></div><div class="aside-copy"><p>导出当前数据，包含题库、计划、试卷、答卷及评分记录。</p><button class="button full" @click="backup"><Icon name="Download" :size="16"/>导出合成数据备份</button></div></section></div></template>
<Modal v-if="resource" :title="resource.title" wide @close="resource=null"><div class="tag-list"><span>{{resource.category}}</span><span>{{resource.author}}</span><Badge text="自制演示资料"/></div><article class="reading-content">{{resource.content}}</article><template #footer><button class="button" @click="download(resource!.title+'.txt',resource!.content);s.audit('学习资源','下载自制资料',resource!.id)"><Icon name="Download" :size="16"/>下载文本</button><button class="button primary" @click="resource=null">完成阅读</button></template></Modal>
<Modal v-if="addOpen" :title="editingId?'维护学习资料':'新增学习资料'" wide @close="addOpen=false"><div class="form-grid"><label>资料名称<input v-model="resourceForm.title"/></label><label>分类<select v-model="resourceForm.category"><option>工业技术</option><option>航空航天</option><option>智能制造</option><option>学习指南</option><option>人文</option><option>社科</option><option>人力资源</option></select></label><label>来源<input v-model="resourceForm.author"/></label><label>上传自制文本（可选）<input type="file" accept=".txt" @change="loadText"/></label><label class="span-two">资料正文<textarea v-model="resourceForm.content" rows="8" placeholder="请输入自制演示正文，不使用无授权图书内容…"/></label></div><template #footer><button class="button primary" @click="addResource">保存为草稿</button></template></Modal>
<Modal v-if="deleteResource" title="删除学习资料" @close="deleteResource=null"><p>确认删除“{{deleteResource.title}}”？正文将从本地演示资料库移除，操作日志保留。</p><template #footer><button class="button" @click="deleteResource=null">取消</button><button class="button danger-outline" @click="removeResource">确认删除资料</button></template></Modal>
<Modal v-if="receipt" title="模拟交换回执" @close="receipt=''"><pre class="protocol-json">{{receipt}}</pre></Modal>
<Modal v-if="exchangePreview" title="模拟同步预览" wide @close="exchangePreview=false"><p>{{exchangeSamples[chosenSystem as ExchangeSystem].description}}</p><pre class="protocol-json">{{JSON.stringify(exchangeSamples[chosenSystem as ExchangeSystem].rows,null,2)}}</pre><template #footer><button class="button" @click="exchangePreview=false">取消</button><button class="button primary" @click="syncSystem">确认模拟同步</button></template></Modal>
<Modal v-if="mapping" title="模拟接口字段映射" wide @close="mapping=false"><div class="notice">字段名为内部契约示例，实际映射以外部接口文档为准。</div><table><thead><tr><th>接口域</th><th>外部示例字段</th><th>内部字段</th><th>规则</th></tr></thead><tbody><tr v-for="r in [['HR人员','employeeCode','person.sourceId','唯一映射，重复更新'],['HR组织','organizationCode','organization.sourceId','编码字典映射'],['考务场次','examSessionCode','session.sourceId','按业务ID去重'],['题库资源','resourceCode / version','question.id / version','来源版本独立保存'],['考试成绩','candidateCode / totalScore','candidate.sourceId / score.total','核定发布后回传'],['回传幂等','session + candidate + version','integration.key','重试保留原键']]"><td>{{r[0]}}</td><td><code>{{r[1]}}</code></td><td><code>{{r[2]}}</code></td><td>{{r[3]}}</td></tr></tbody></table></Modal>
</template>
